<?php
include '../include/settings.php';include '../include/include.php';include '../modules/system.php';
$HD_CURPAGE='tasks.php';if(($_SESSION['login_type']??$LOGIN_INVALID)==$LOGIN_INVALID){header('Location: index.php?redirect=tasks.php');exit;}
$uid=(int)$_SESSION['user']['id'];$module_priv=get_row_count("SELECT COUNT(*) FROM {$pre}privilege WHERE user_id=$uid AND dept_id=0")>0;if(!$module_priv||!hd_module_enabled('tasks')||!hd_module_load('tasks')||!tasks_installed()){header('Location: modules.php');exit;}
$csrf=$_SESSION['tasks_csrf']??'';if($csrf===''){$csrf=bin2hex(random_bytes(32));$_SESSION['tasks_csrf']=$csrf;}$msg='';
function task_escape($v){return hd_module_escape($v);}function task_date_valid($v){if($v==='')return true;$d=DateTime::createFromFormat('Y-m-d',$v);return $d&&$d->format('Y-m-d')===$v;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!isset($_POST['csrf_token'])||!hash_equals($csrf,(string)$_POST['csrf_token']))$msg='<div class="alert alert-danger">The request could not be verified.</div>';
 else{$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);
  if($action==='save'){$title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$priority=(string)($_POST['priority']??'normal');$due=trim((string)($_POST['due_date']??''));$assigned=(int)($_POST['assigned_to']??0);$user_ok=$assigned===0||get_row_count("SELECT COUNT(*) FROM {$pre}user WHERE id=$assigned")>0;if($title===''||strlen($title)>255||!in_array($priority,array('low','normal','high'),true)||!task_date_valid($due)||!$user_ok)$msg='<div class="alert alert-danger">Check the title, priority, due date, and assignee.</div>';else{$t=task_escape($title);$d=task_escape($description);$p=task_escape($priority);$date=$due===''?'NULL':"'".task_escape($due)."'";$now=time();if($id)mysql_query("UPDATE {$pre}task SET title='$t',description='$d',priority='$p',due_date=$date,assigned_to=$assigned,updated_at=$now WHERE id=$id");else mysql_query("INSERT INTO {$pre}task(title,description,priority,due_date,assigned_to,created_by,created_at,updated_at) VALUES('$t','$d','$p',$date,$assigned,$uid,$now,$now)");header('Location: tasks.php?saved=1');exit;}}
  elseif($action==='toggle'&&$id){$complete=(int)($_POST['complete']??0);$now=time();mysql_query("UPDATE {$pre}task SET is_complete=$complete,completed_by=".($complete?$uid:0).",completed_at=".($complete?$now:0).",updated_at=$now WHERE id=$id");header('Location: tasks.php?updated=1');exit;}
  elseif($action==='delete'&&$id){mysql_query("DELETE FROM {$pre}task WHERE id=$id");header('Location: tasks.php?deleted=1');exit;}
 }
}
$edit=false;if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$r=mysql_query("SELECT * FROM {$pre}task WHERE id=$id");$edit=$r?mysql_fetch_array($r,MYSQLI_ASSOC):false;}
$filter=(string)($_GET['status']??'open');if(!in_array($filter,array('open','overdue','completed','all'),true))$filter='open';$where=$filter==='open'?'WHERE t.is_complete=0':($filter==='completed'?'WHERE t.is_complete=1':($filter==='overdue'?"WHERE t.is_complete=0 AND t.due_date IS NOT NULL AND t.due_date<CURDATE()":''));
$tasks=mysql_query("SELECT t.*,u.name assigned_name,c.name creator_name FROM {$pre}task t LEFT JOIN {$pre}user u ON u.id=t.assigned_to LEFT JOIN {$pre}user c ON c.id=t.created_by $where ORDER BY t.is_complete,t.due_date IS NULL,t.due_date,t.id DESC");$users=mysql_query("SELECT id,name FROM {$pre}user ORDER BY name");$user_options=array();while($users&&($u=mysql_fetch_array($users,MYSQLI_ASSOC)))$user_options[]=$u;$script_name='Task Manager';include './include/header.php';
?>
<div class="d-sm-flex align-items-center justify-content-between mb-4"><div><h1 class="h3 mb-1 text-gray-800">Task Manager</h1><p class="mb-0 text-muted">Assign work, track deadlines, and follow progress.</p></div><div class="mt-3 mt-sm-0"><button class="btn btn-sm btn-primary" data-toggle="collapse" data-target="#task-editor"><i class="fas fa-plus mr-1"></i>New task</button></div></div>
<?php echo $msg;if(isset($_GET['saved']))echo '<div class="alert alert-success">Task saved.</div>';elseif(isset($_GET['updated']))echo '<div class="alert alert-success">Task status updated.</div>';elseif(isset($_GET['deleted']))echo '<div class="alert alert-success">Task deleted.</div>'; ?>
<div class="collapse <?php echo $edit||$msg?'show':''?>" id="task-editor"><div class="card shadow-sm mb-4 border-left-primary"><div class="card-header"><h2 class="h6 mb-0 font-weight-bold text-primary"><?php echo $edit?'Edit task':'New task'?></h2></div><div class="card-body"><form method="post"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf,ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?php echo (int)($edit['id']??0)?>"><div class="form-group"><label>Title</label><input class="form-control" name="title" maxlength="255" required value="<?php echo htmlspecialchars($edit['title']??($_POST['title']??''),ENT_QUOTES,'UTF-8')?>"></div><div class="form-group"><label>Description</label><textarea class="form-control no-tinymce" name="description" rows="4"><?php echo htmlspecialchars($edit['description']??($_POST['description']??''),ENT_QUOTES,'UTF-8')?></textarea></div><div class="form-row"><div class="form-group col-md-4"><label>Priority</label><select class="form-control" name="priority"><?php $selected=$edit['priority']??($_POST['priority']??'normal');foreach(array('low'=>'Low','normal'=>'Normal','high'=>'High')as$v=>$label):?><option value="<?php echo $v?>" <?php echo $selected===$v?'selected':''?>><?php echo $label?></option><?php endforeach;?></select></div><div class="form-group col-md-4"><label>Due date</label><input class="form-control" type="date" name="due_date" value="<?php echo htmlspecialchars($edit['due_date']??($_POST['due_date']??''),ENT_QUOTES,'UTF-8')?>"></div><div class="form-group col-md-4"><label>Assigned to</label><select class="form-control" name="assigned_to"><option value="0">Unassigned</option><?php $assigned=(int)($edit['assigned_to']??($_POST['assigned_to']??0));foreach($user_options as$u):?><option value="<?php echo(int)$u['id']?>" <?php echo $assigned===(int)$u['id']?'selected':''?>><?php echo htmlspecialchars($u['name'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></div></div><div class="text-right"><?php if($edit):?><a class="btn btn-light mr-2" href="tasks.php">Cancel</a><?php endif;?><button class="btn btn-primary"><i class="fas fa-save mr-1"></i>Save task</button></div></form></div></div></div>
<div class="card shadow-sm"><div class="card-header d-flex flex-wrap justify-content-between align-items-center"><h2 class="h6 mb-2 mb-sm-0 font-weight-bold text-primary">Tasks</h2><div class="btn-group btn-group-sm"><?php foreach(array('open'=>'Open','overdue'=>'Overdue','completed'=>'Completed','all'=>'All')as$v=>$label):?><a class="btn btn-<?php echo $filter===$v?($v==='overdue'?'danger':'primary'):'outline-secondary'?>" href="tasks.php?status=<?php echo $v?>"><?php echo $label?></a><?php endforeach;?></div></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Task</th><th>Assigned to</th><th>Priority</th><th>Due</th><th>Status</th><th class="text-right">Actions</th></tr></thead><tbody><?php $count=0;while($tasks&&($task=mysql_fetch_array($tasks,MYSQLI_ASSOC))):$count++;$overdue=!$task['is_complete']&&$task['due_date']&&$task['due_date']<date('Y-m-d');?><tr class="<?php echo $overdue?'table-danger':''?>"><td><strong><?php echo htmlspecialchars($task['title'],ENT_QUOTES,'UTF-8')?></strong><?php if($task['description']):?><small class="d-block text-muted"><?php echo htmlspecialchars(substr($task['description'],0,100),ENT_QUOTES,'UTF-8')?></small><?php endif;?></td><td><?php echo htmlspecialchars($task['assigned_name']?:'Unassigned',ENT_QUOTES,'UTF-8')?></td><td><span class="badge badge-<?php echo $task['priority']==='high'?'danger':($task['priority']==='low'?'secondary':'info')?>"><?php echo ucfirst($task['priority'])?></span></td><td><?php echo $task['due_date']?htmlspecialchars($task['due_date'],ENT_QUOTES,'UTF-8'):'<span class="text-muted">None</span>'?></td><td><span class="badge badge-<?php echo $task['is_complete']?'success':'warning'?>"><?php echo $task['is_complete']?'Complete':'Open'?></span></td><td class="text-right text-nowrap"><form method="post" class="d-inline"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf,ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?php echo(int)$task['id']?>"><input type="hidden" name="complete" value="<?php echo $task['is_complete']?0:1?>"><button class="btn btn-sm btn-outline-success" title="<?php echo $task['is_complete']?'Reopen':'Complete'?>"><i class="fas fa-<?php echo $task['is_complete']?'undo':'check'?>"></i></button></form><a class="btn btn-sm btn-outline-primary" href="tasks.php?edit=<?php echo(int)$task['id']?>"><i class="fas fa-edit"></i></a><form method="post" class="d-inline" onsubmit="return confirm('Delete this task?')"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf,ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?php echo(int)$task['id']?>"><button class="btn btn-sm btn-outline-danger"><i class="fas fa-trash"></i></button></form></td></tr><?php endwhile;if(!$count):?><tr><td colspan="6" class="text-center text-muted py-5"><i class="fas fa-clipboard-check fa-2x mb-2 d-block"></i>No tasks found for this filter.</td></tr><?php endif;?></tbody></table></div></div>
